use vstd::prelude::*;

verus! {
    ///
    /// Given a three‐digit integer n ∈ [100,999], construct
    /// a Vec<char> of length exactly 6 whose first three
    /// entries are 'A','B','C' and whose last three entries
    /// are the decimal digits of n in order.
    ///
    fn solve(n: i8) -> (result: Vec<char>)
        requires
            // n is guaranteed to be a three‐digit number
            100 <= n && n <= 999,
        ensures
            // The output is length 6:
            result.len() == 6 &&
            // The first three characters are 'A','B','C'
            result[0] == 'A' &&
            result[1] == 'B' &&
            result[2] == 'C' &&
            // The last three characters are the decimal digits of n
            // (we cast u8 → char by adding to ASCII '0')
            result[3] == ((n / 100)   as u8 + b'0') as char &&
            result[4] == (((n % 100) / 10) as u8 + b'0') as char &&
            result[5] == ((n % 10)    as u8 + b'0') as char
    {
        // Build the result vector
        let mut res: Vec<char> = Vec::new();
        res.push('A');
        res.push('B');
        res.push('C');

        // Extract digits
        let hundreds: u8 = (n / 100)     as u8;  // in 1..=9
        let tens:     u8 = ((n % 100) / 10) as u8;  // in 0..=9
        let ones:     u8 = (n % 10)      as u8;  // in 0..=9

        // Convert each digit to its ASCII‐digit char
        let c1: char = (hundreds + b'0') as char;
        let c2: char = (tens     + b'0') as char;
        let c3: char = (ones     + b'0') as char;

        res.push(c1);
        res.push(c2);
        res.push(c3);

        // A final sanity check
        assert(res.len() == 6);

        result = res;
    }
}

